#!/usr/bin/env node
// Regenerate typed ABI modules from a compiler ABI handoff.
//   node scripts/gen-abis.mjs <handoff-dir>
// <handoff-dir> holds current/*.json, shared/*.json and legacy-reference/*.json
// (arrays of ABI items, as exported by `forge inspect <Contract> abi`).
// Output: src/lib/abis/masonry/<name>.ts with `as const` arrays so viem infers
// argument and return types. Nothing is hand-edited in the generated files.
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";

const src = process.argv[2];
if (!src) {
  console.error("usage: node scripts/gen-abis.mjs <handoff-dir>");
  process.exit(1);
}
const out = new URL("../src/lib/abis/masonry/", import.meta.url).pathname;
mkdirSync(out, { recursive: true });

const camel = (s) => s.replace(/^I(?=[A-Z])/, "i").replace(/^[A-Z]/, (c) => c.toLowerCase());
const groups = { current: "current", shared: "shared", "legacy-reference": "legacy" };
const index = [];
for (const [dir, kind] of Object.entries(groups)) {
  let files = [];
  try {
    files = readdirSync(join(src, dir)).filter((f) => f.endsWith(".json")).sort();
  } catch {
    continue;
  }
  for (const f of files) {
    const name = basename(f, ".json");
    const abi = JSON.parse(readFileSync(join(src, dir, f), "utf8"));
    if (!Array.isArray(abi)) throw new Error(`${dir}/${f}: expected an ABI array`);
    const id = `${camel(name)}Abi`;
    const file = kind === "legacy" ? `legacy${name}` : name;
    writeFileSync(
      join(out, `${file}.ts`),
      `// Generated by scripts/gen-abis.mjs from ${dir}/${f} — do not edit.\n` +
        `// ${kind === "legacy" ? "Old Money reference interface: study only, never wired to xTOMB writes." : "Source: 0xbasedev/v4-tomb merge @ 7e3115f."}\n` +
        `export const ${kind === "legacy" ? `legacy${name}Abi` : id} = ${JSON.stringify(abi)} as const;\n`,
    );
    index.push(`export { ${kind === "legacy" ? `legacy${name}Abi` : id} } from "./${file}";`);
  }
}
writeFileSync(join(out, "index.ts"), `// Generated by scripts/gen-abis.mjs — do not edit.\n${index.join("\n")}\n`);
console.log(`wrote ${index.length} ABI modules to src/lib/abis/masonry/`);
